using Microsoft.AspNetCore.Http; using Microsoft.Extensions.Logging; using OrcaFacil.Application.Abstractions; using OrcaFacil.Domain.Entities; using OrcaFacil.Domain.Enums; using QuestPDF.Fluent; using QuestPDF.Helpers; using QuestPDF.Infrastructure;
namespace OrcaFacil.Infrastructure;
public class BCryptPasswordHasher:IPasswordHasher{ public string Hash(string password)=>BCrypt.Net.BCrypt.HashPassword(password); public bool Verify(string password,string hash)=>BCrypt.Net.BCrypt.Verify(password,hash); }
public class QuestPdfDocumentService:IPdfService{ public Task<byte[]> GenerateDocumentPdfAsync(Document document, IssuerProfile? issuer, PlanType plan, CancellationToken ct=default){ QuestPDF.Settings.License=LicenseType.Community; var bytes=Document.Create(c=>c.Page(p=>{p.Margin(32);p.Header().Text($"OrçaFácil - {document.Type} {document.Number}").Bold().FontSize(18);p.Content().Column(col=>{col.Item().Text($"Emitente: {issuer?.BusinessName ?? "Não informado"}"); col.Item().Text($"Cliente: {document.ClientName}"); foreach(var i in document.Items) col.Item().Text($"{i.Description} - {i.Quantity} x {i.UnitPrice:C} = {i.Total:C}"); col.Item().Text($"Total: {document.Total:C}").Bold(); if(plan==PlanType.Free) col.Item().Text("Gerado no plano Free do OrçaFácil").FontColor(Colors.Grey.Medium);});p.Footer().AlignCenter().Text("MNSOFT - comercial@mnsoft.com.br");})).GeneratePdf(); return Task.FromResult(bytes); }}
public class CorrelationIdMiddleware(RequestDelegate next){ public async Task Invoke(HttpContext ctx){ var id=ctx.Request.Headers["X-Correlation-Id"].FirstOrDefault()??Guid.NewGuid().ToString("N"); ctx.Response.Headers["X-Correlation-Id"]=id; await next(ctx);} }
public class ExceptionHandlingMiddleware(RequestDelegate next,ILogger<ExceptionHandlingMiddleware> log){ public async Task Invoke(HttpContext ctx){ try{await next(ctx);}catch(Exception ex){log.LogError(ex,"Unhandled exception"); ctx.Response.StatusCode=500; await ctx.Response.WriteAsJsonAsync(new{error="Erro interno",correlationId=ctx.Response.Headers["X-Correlation-Id"].ToString()});}}}
